    val id: String,
    val layout: DesignSystemLayout? = null,
    val license: String? = null,
    val motion: DesignSystemMotion? = null,
    val name: String,
    val owner: String? = null,
    val shape: DesignSystemShape? = null,
    val space: DesignSystemSpace? = null,
    val surface: DesignSystemSurface? = null,
    val tags: List<String>? = null,
    val typography: DesignSystemTypography? = null,
    val variants: Map<String, DesignSystemVariant>? = null,
    val version: String,
    val voice: DesignSystemVoice? = null,
) {
    companion object {
        private val FIELDS = setOf("accessibility", "assets", "color", "components", "description", "elevation", "extends", "format", "formatVersion", "icons", "id", "layout", "license", "motion", "name", "owner", "shape", "space", "surface", "tags", "typography", "variants", "version", "voice")

        fun decode(json: JsonValue, path: String = "\$"): DesignSystem {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return DesignSystem(
                accessibility = fields["accessibility"]?.let { DesignSystemAccessibility.decode(it, "$path.accessibility") },
                assets = fields["assets"]?.let { DesignSystemAssets.decode(it, "$path.assets") },
                color = fields["color"]?.let { DesignSystemColor.decode(it, "$path.color") },
                components = fields["components"]?.let { DesignSystemComponents.decode(it, "$path.components") },
                description = fields["description"]?.let { it.str("$path.description") },
                elevation = fields["elevation"]?.let { DesignSystemElevation.decode(it, "$path.elevation") },
                extends = fields["extends"]?.let { it.str("$path.extends") },
                format = fields.required("format", path).constant("texuli/design-system", "$path.format"),
                formatVersion = fields.required("formatVersion", path).constant(1L, "$path.formatVersion"),
                icons = fields["icons"]?.let { DesignSystemIcons.decode(it, "$path.icons") },
                id = fields.required("id", path).str("$path.id"),
                layout = fields["layout"]?.let { DesignSystemLayout.decode(it, "$path.layout") },
                license = fields["license"]?.let { it.str("$path.license") },
                motion = fields["motion"]?.let { DesignSystemMotion.decode(it, "$path.motion") },
                name = fields.required("name", path).str("$path.name"),
                owner = fields["owner"]?.let { it.str("$path.owner") },
                shape = fields["shape"]?.let { DesignSystemShape.decode(it, "$path.shape") },
                space = fields["space"]?.let { DesignSystemSpace.decode(it, "$path.space") },
                surface = fields["surface"]?.let { DesignSystemSurface.decode(it, "$path.surface") },
                tags = fields["tags"]?.let { ("$path.tags").let { p -> it.arrValues(p).mapIndexed { i, item -> item.str("$p[$i]") } } },
                typography = fields["typography"]?.let { DesignSystemTypography.decode(it, "$path.typography") },
